"""Non-numerical final delivery and history checks."""
from collections import Counter
import hashlib
import json
from pathlib import Path
import subprocess
import yaml

ROOT = Path.cwd()
TASK = ROOT / 'artifacts/gpup-fp4-proto-v1'
OUT = ROOT / 'docs/benchmarks/data'


def git(*args):
    return subprocess.check_output(['git', *args], text=True)


def read(path):
    return json.loads(path.read_text())


allowed = {'AGENTS.md', 'CHANGELOG.md', 'README.md', 'state/active-task.md', 'state/backlog.yaml',
           'state/known-failures.md', 'wiki/status.md', 'docs/plans/gpu-lp-precision-roadmap.md',
           'docs/plans/lp-fp4-persistent-state.md'}
changed = set(git('diff', 'HEAD', '--name-only').splitlines())
assert changed <= allowed, changed - allowed
for name in ('AGENTS.md', 'CHANGELOG.md', 'state/active-task.md', 'state/known-failures.md', 'wiki/status.md'):
    old = git('show', 'HEAD:' + name)
    old_body = old.split('\n', 1)[1]
    assert (ROOT / name).read_text().endswith(old_body), name
old = yaml.safe_load(git('show', 'HEAD:state/backlog.yaml'))
new = yaml.safe_load((ROOT / 'state/backlog.yaml').read_text())
tasks = {t['id']: t for t in new['tasks']}
assert len(tasks) == len(new['tasks'])
for t in old['tasks']:
    if t['status'] == 'complete':
        assert tasks[t['id']] == t
assert new['next_ready_task'] == 'GPUP-FP4-RECOVERY-SPEC'
assert tasks['GPUP-FP4-PROTO']['status'] == 'in_progress'
visiting, done = set(), set()


def visit(name):
    assert name in tasks and name not in visiting
    if name in done:
        return
    visiting.add(name)
    for dependency in tasks[name]['depends_on']:
        visit(dependency)
    visiting.remove(name)
    done.add(name)


for name, task in tasks.items():
    visit(name)
    if task['status'] == 'ready':
        assert all(tasks[d]['status'] == 'complete' for d in task['depends_on'])
manifest = read(OUT / 'fp4-proto-manifest-v1.json')
for r in manifest['sources'] + [manifest['fixtures'], manifest['proposal']]:
    assert hashlib.sha256((ROOT / r['path']).read_bytes()).hexdigest() == r['sha256']
for r in read(OUT / 'fp4-proto-evidence-v1.json')['files']:
    data = r['utf8'].encode()
    assert len(data) == r['bytes'] and hashlib.sha256(data).hexdigest() == r['sha256']
    assert data == (ROOT / r['path']).read_bytes()
for name in ('tools/lp_fp4_reference_v2.py', 'tests/integration/test_lp_fp4_reference_v2.py'):
    assert (ROOT / name).read_bytes() == (TASK / 'development-v2-sources' / name).read_bytes()
result = read(OUT / 'fp4-proto-result-v1.json')
assert Counter(r['refusal']['reason'] for r in result['rows']) == {
    'cumulative_enclosure_guard': 9, 'contract_refusal': 3}
assert (OUT / 'fp4-proto-result-v1.json').read_bytes() == (TASK / 'qualification-v1/result.json').read_bytes()
for command in (['git', 'diff', '--check'], ['python3', '-B', 'tools/validate_artifacts.py'],
                ['python3', '-B', 'tools/build_docs.py']):
    subprocess.run(command, check=True)
print('Delivery: historical sources/results unchanged, exact evidence verified, backlog acyclic and ready, docs/artifacts/diff pass.')

